import java.util.Objects;
public final class MaterialKey {
    private final String area;
    private final String material;
    public MaterialKey(String area, String material) {
        if (area == null || material == null || !area.matches("[A-Z]{1,8}") || !material.matches("[a-z]{1,12}")) throw new IllegalArgumentException("Invalid material key");
        this.area = area; this.material = material;
    }
    public String area() { return area; }
    public String material() { return material; }
    @Override public boolean equals(Object other) {
        if (this == other) return true;
        if (!(other instanceof MaterialKey)) return false;
        MaterialKey key = (MaterialKey) other;
        return area.equals(key.area) && material.equals(key.material);
    }
    @Override public int hashCode() { return Objects.hash(area, material); }
}

import java.util.Objects;
public record StockEntry(MaterialKey key, int units) {
    public StockEntry {
        Objects.requireNonNull(key, "key");
        if (units < 0 || units > 1000) throw new IllegalArgumentException("Invalid units");
    }
}

import java.io.*;
import java.util.*;
public final class LedgerParser {
    private LedgerParser() {}
    public static List<StockEntry> read(Reader reader) throws IOException {
        BufferedReader buffered = reader instanceof BufferedReader ? (BufferedReader) reader : new BufferedReader(reader);
        List<StockEntry> entries = new ArrayList<>();
        String line;
        int number = 0;
        while ((line = buffered.readLine()) != null) {
            number++;
            String[] fields = line.split("~", -1);
            try {
                if (fields.length != 3) throw new IllegalArgumentException();
                int units = Integer.parseInt(fields[2]);
                if (!Integer.toString(units).equals(fields[2])) throw new IllegalArgumentException();
                entries.add(new StockEntry(new MaterialKey(fields[0], fields[1]), units));
            } catch (IllegalArgumentException error) { throw new IOException("Invalid material record at line " + number, error); }
        }
        return entries;
    }
}

import java.util.*;
public final class LedgerTotals {
    private LedgerTotals() {}
    public static List<String> lines(List<StockEntry> entries) {
        Map<MaterialKey, Long> totals = new HashMap<>();
        for (StockEntry entry : entries) totals.put(entry.key(), totals.getOrDefault(entry.key(), 0L) + entry.units());
        List<MaterialKey> keys = new ArrayList<>(totals.keySet());
        keys.sort(Comparator.comparing(MaterialKey::area).thenComparing(MaterialKey::material));
        List<String> output = new ArrayList<>();
        for (MaterialKey key : keys) output.add(key.area() + "/" + key.material() + "=" + totals.get(key));
        return output;
    }
}

import java.io.*;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
public final class LedgerCli {
    private LedgerCli() {}
    public static int run(String[] args, PrintStream out, PrintStream err) {
        if (args.length != 2) { err.println("Usage: LedgerCli input output"); return 2; }
        try {
            List<StockEntry> entries;
            try (BufferedReader reader = Files.newBufferedReader(Path.of(args[0]), StandardCharsets.UTF_8)) { entries = LedgerParser.read(reader); }
            List<String> lines = LedgerTotals.lines(entries);
            try (BufferedWriter writer = Files.newBufferedWriter(Path.of(args[1]), StandardCharsets.UTF_8)) {
                for (String line : lines) writer.write(line + "\n");
            }
            out.println("Wrote " + lines.size() + " totals.");
            return 0;
        } catch (IOException | InvalidPathException error) { err.println(error.getMessage()); return 1; }
    }
    public static void main(String[] args) { run(args, System.out, System.err); }
}
